rank=path.rank(axis=1,pct=True); print('turnover',round((rank-rank.shift()).abs().stack().groupby(level=0).mean().dropna().mean(),6));path.to_csv('scripts/miner_2_20290503_path_efficiency_signal.csv',index_label='date')
